//! The `bsc network` subcommand — the network-specific shim over the shared verbatim-JSON-per-id
//! store CLI ([`bsc_json_store::cli`], #2158).
//!
//! A **network** is a domain that owns a set of projects and exactly one architect session. This store
//! holds the network entity only; a project's MEMBERSHIP is the `network` column on its project row,
//! set with `bsc project network set|clear` — the same seam `architect` already uses.
//!
//! Dispatched by the unified `bsc` binary (#1877) via [`run`]; the per-command help (#1762):
//!   bsc network help          # compact menu (the small "what commands exist" prompt)
//!   bsc network get help      # detailed help for ONE command
//!
//! The store is located via `--dir <path>` or the `BSC_NETWORK_DIR` env var (set per-session at
//! launch), defaulting to `~/.base-studio-code/networks.db`.

use bsc_cli_util::CmdDoc;
use bsc_json_store::cli::CliSpec;

const TAGLINE: &str =
    "the user network store — a domain that owns a set of projects and one architect session";

/// The command catalog — drives both dispatch and the shared help system. One detailed `usage` block
/// per command keeps the overview tiny and the detail one-fetch-away.
/// The crate's own verb catalog. `pub` so `bsc surface verbs` and the Glance crate drill can PROJECT
/// it rather than restate it — a generated catalog cannot drift, a second list does.
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "new",
        summary: "create a network from a NAME; mints its id and prints it",
        usage: "\
USAGE:
  bsc network new <name>… [--pretty]

Creates a network and prints its id. The name may contain spaces — every argument is joined, so
`bsc network new cash flow` and `bsc network new \"cash flow\"` are the same thing.

THE NAME BECOMES THE ID, and the id is FROZEN: `network-<slug>`, lowercase [a-z0-9-]. A colliding
name gets a fresh id (`network-cash-flow-2`) rather than overwriting — the convention every in-app
library uses, and the reason this is not the `projectSlug`-plus-collision-modal discipline: that one
exists where an id names an on-disk hub recovered by derivation, and a network is a row.

The id is frozen because the architect's pane id (`network-<slug>:architect`) and its workspace
directory derive from it, so changing it would strand a running session. Change the NAME with
`bsc network rename`; it is display-only and safe.",
    },
    CmdDoc {
        name: "rename",
        summary: "change a network's display name (never its id)",
        usage: "\
USAGE:
  bsc network rename <id> <name>… [--pretty]

Sets the name shown on the Glance tab. DISPLAY ONLY — the id is untouched, because the architect's
pane id and workspace directory derive from it.

An empty name is refused rather than stored: a blank tab label is indistinguishable from a broken
one.",
    },
    CmdDoc {
        name: "list",
        summary: "every network's {id, name, architect} (JSON)",
        usage: "\
USAGE:
  bsc network list [--full] [--pretty]

Prints every network's { id, name, architect } as JSON (compact; --pretty for indented). --full emits
the COMPLETE network objects, which is what the desktop hydration reads.

A network is a DOMAIN: the set of projects that belong to one concern, drawn as one Glance tab. Which
projects are in it is NOT stored here — it is the `network` column on each project row, so read that
with `bsc project list` rather than expecting a member list on the network.",
    },
    CmdDoc {
        name: "get",
        summary: "print one network (JSON, verbatim) or null",
        usage: "\
USAGE:
  bsc network get <id> [--pretty]

Prints the stored network JSON for <id> verbatim, or `null` if absent.",
    },
    CmdDoc {
        name: "set",
        summary: "upsert from network JSON on stdin; prints id(s)",
        usage: "\
USAGE:
  bsc network set [--pretty]   # network JSON (one object or an array) on stdin

Upserts each network by its (required, non-empty) \"id\" field, written verbatim. Prints the id(s)
written.

SHAPE: { \"id\": \"network-kitchen\", \"name\": \"kitchen\", \"architect\": \"persona-architect\",
         \"position\": 0 }

  id         frozen at creation. The architect's pane id (`network-<id>:architect`) and its workspace
             dir are derived from it, so a changed id strands a running session. Rename the `name`.
  name       what the Glance tab shows. Display-only; change it freely.
  architect  optional persona id. Absent means the default architect persona.
  position   tab order.

The write is VERBATIM, so a field this CLI has no model for survives a round-trip — the same contract
every other json-store shim keeps.",
    },
    CmdDoc {
        name: "remove",
        summary: "delete a network (no-op if absent)",
        usage: "\
USAGE:
  bsc network remove <id> [--pretty]

Deletes the network keyed by <id>. A no-op (not an error) when it does not exist.

THIS DOES NOT REASSIGN ITS PROJECTS. A project whose `network` column still names a removed network is
unassigned in effect, not broken — clear or move it first with `bsc project network set|clear` if you
want it somewhere. Removing the network a project points at is recoverable; renaming its id is not.",
    },
];

/// The network store's concrete knobs over the shared CLI (#2158): its noun, env var, dir segment,
/// help catalog, and the `{id, name, architect}` lean-`list` projection.
///
/// `meta_fields` carries `architect` alongside the usual `{id, name}` because "who is the architect of
/// this network" is the question the lean list exists to answer — one fetch, no `--full`.
const SPEC: CliSpec = CliSpec {
    noun: "network",
    dir_env: "BSC_NETWORK_DIR",
    dir_segment: "networks",
    tagline: TAGLINE,
    commands: COMMANDS,
    meta_fields: &["id", "name", "architect"],
    graph_fields: &[],
    field_aliases: &[],
};

/// The `network` subcommand entrypoint: `args` is everything after `bsc network`; `prog` is the
/// display name for help/errors. Delegates to the shared dispatch with the network [`SPEC`].
pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    // `new` and `rename` are intercepted BEFORE delegating: the shared store CLI is a verbatim-JSON
    // CRUD surface and knows nothing about minting an id from a name, so it would reject them as
    // unknown commands. `help` still lists them — the catalog above is what the shared help renders.
    // Same shape as `bsc teams model`.
    match args.first().map(String::as_str) {
        Some("new") if args.get(1).map(String::as_str) != Some("help") => return cmd_new(&args, prog),
        Some("rename") if args.get(1).map(String::as_str) != Some("help") => return cmd_rename(&args, prog),
        _ => {}
    }
    bsc_json_store::cli::run(args, prog, &SPEC)
}

/// `network-<slug>` from a display name — THE id-minting rule, and the only copy that decides.
///
/// The frontend has a mirror of this in `mintNetworkId` for its optimistic cache, but the CLI is what
/// a session and a user reach, so the rule lives here. The character class is narrower than a display
/// name allows on purpose: the id becomes a pane key (`network-<slug>:architect`) and a directory name,
/// and `bsc_session::network_architect_slug` refuses anything outside `[a-z0-9-]`. A name that slugs to
/// nothing still yields a usable id rather than a bare `network-`.
fn mint_id(existing: &[String], name: &str) -> String {
    let slug: String = name
        .to_lowercase()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
        .collect::<String>()
        .split('-')
        .filter(|p| !p.is_empty())
        .collect::<Vec<_>>()
        .join("-")
        .chars()
        .take(60)
        .collect();
    let base = format!("network-{}", if slug.is_empty() { "network" } else { &slug });
    if !existing.iter().any(|e| e == &base) {
        return base;
    }
    let mut n = 2;
    while existing.iter().any(|e| e == &format!("{base}-{n}")) {
        n += 1;
    }
    format!("{base}-{n}")
}

/// Open the network store the same way every verb does — `--dir` → `$BSC_NETWORK_DIR` → the default.
fn open_store(args: &[String], prog: &str) -> Result<bsc_json_store::Store, String> {
    let dir_flag = args
        .iter()
        .position(|a| a == "--dir")
        .and_then(|i| args.get(i + 1))
        .cloned();
    let dir = bsc_cli_util::resolve_store_path(&dir_flag, SPEC.dir_env, || {
        bsc_util::bsc_base_dir()
            .map(|b| b.join(SPEC.dir_segment))
            .ok_or_else(|| format!("{prog}: could not resolve the network store; set HOME/USERPROFILE or pass --dir"))
    })?;
    Ok(bsc_json_store::Store::new(dir, SPEC.noun))
}

/// Every argument after the verb that is not a flag or a flag's value, joined — so a name with spaces
/// needs no quoting.
fn joined_name(args: &[String], skip: usize) -> String {
    let mut out: Vec<&str> = Vec::new();
    let mut it = args.iter().skip(skip).peekable();
    while let Some(a) = it.next() {
        if a == "--dir" {
            it.next();
            continue;
        }
        if a.starts_with("--") {
            continue;
        }
        out.push(a);
    }
    out.join(" ").trim().to_string()
}

fn cmd_new(args: &[String], prog: &str) -> Result<(), String> {
    let name = joined_name(args, 1);
    if name.is_empty() {
        return Err(format!("usage: {prog} new <name>"));
    }
    let store = open_store(args, prog)?;
    // Existing ids, for the collision walk. Read from the store rather than tracked separately: two
    // sources for "which ids are taken" is how a mint starts overwriting.
    let rows = store.list();
    let existing: Vec<String> = rows
        .iter()
        .filter_map(|r| serde_json::from_str::<serde_json::Value>(r).ok())
        .filter_map(|v| v.get("id").and_then(|i| i.as_str()).map(str::to_string))
        .collect();
    let id = mint_id(&existing, &name);
    let position = existing.len() as i64;
    let row = serde_json::json!({ "id": id, "name": name, "position": position });
    store.set(&id, &serde_json::to_string(&row).map_err(|e| format!("{prog} new: {e}"))?)?;
    println!("{id}");
    Ok(())
}

fn cmd_rename(args: &[String], prog: &str) -> Result<(), String> {
    let id = args
        .get(1)
        .filter(|a| !a.starts_with("--"))
        .ok_or_else(|| format!("usage: {prog} rename <id> <name>"))?;
    let name = joined_name(args, 2);
    if name.is_empty() {
        // Refused rather than stored: a blank tab label is indistinguishable from a broken one.
        return Err(format!("usage: {prog} rename <id> <name>  (a name cannot be empty)"));
    }
    let store = open_store(args, prog)?;
    let raw = store
        .get(id)?
        .ok_or_else(|| format!("{prog} rename: no network '{id}' (list them with `{prog} list`)"))?;
    let mut v: serde_json::Value =
        serde_json::from_str(&raw).map_err(|e| format!("{prog} rename: '{id}' is not valid JSON: {e}"))?;
    // The NAME only. The id is re-pinned rather than left to the patch, so a rename can never move it.
    v["name"] = serde_json::Value::String(name);
    v["id"] = serde_json::Value::String(id.clone());
    store.set(id, &serde_json::to_string(&v).map_err(|e| format!("{prog} rename: {e}"))?)?;
    println!("{id}");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Freezes the store's identity. These four values are what bind the CLI to a location on disk:
    /// change one and every existing user's networks become invisible without a single test failing
    /// elsewhere. Every shim pins them for that reason.
    /// The id-minting rule, pinned against the SAME hostile names the frontend's `mintNetworkId` test
    /// uses. Two copies of a rule drift; this is the one that decides, and the pair of tests is what
    /// says so out loud.
    #[test]
    fn mint_id_slugs_and_auto_disambiguates() {
        assert_eq!(mint_id(&[], "Finance"), "network-finance");
        assert_eq!(mint_id(&["network-finance".into()], "Finance"), "network-finance-2");
        assert_eq!(
            mint_id(&["network-finance".into(), "network-finance-2".into()], "finance"),
            "network-finance-3",
        );
    }

    /// The id becomes a PANE KEY (`network-<slug>:architect`) and a DIRECTORY NAME, and
    /// `bsc_session::network_architect_slug` refuses anything outside `[a-z0-9-]`. A name that slugs to
    /// nothing must still yield a usable id rather than a bare `network-`.
    #[test]
    fn a_minted_id_is_always_a_legal_pane_key() {
        for name in ["Cash & Flow", "  spaced  out  ", "../escape", "ÜNICODE", "!!!", "a/b", "x;y"] {
            let id = mint_id(&[], name);
            let slug = id.strip_prefix("network-").expect("every id carries the prefix");
            assert!(!slug.is_empty(), "{name} -> {id}");
            assert!(
                slug.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'),
                "{name} -> {id} must be a legal pane key",
            );
        }
        assert_eq!(mint_id(&[], "!!!"), "network-network");
        assert_eq!(mint_id(&[], "Cash & Flow"), "network-cash-flow");
    }

    /// A name with spaces needs no quoting — every non-flag argument is joined — and `--dir` takes its
    /// value with it rather than leaking into the name.
    #[test]
    fn the_name_is_every_non_flag_argument_joined() {
        let args: Vec<String> = ["new", "cash", "flow", "--dir", "/tmp/x", "--pretty"]
            .iter().map(|s| s.to_string()).collect();
        assert_eq!(joined_name(&args, 1), "cash flow");
    }

    #[test]
    fn spec_pins_the_store_identity() {
        assert_eq!(SPEC.noun, "network");
        assert_eq!(SPEC.dir_env, "BSC_NETWORK_DIR");
        assert_eq!(SPEC.dir_segment, "networks");
        assert_eq!(SPEC.meta_fields, &["id", "name", "architect"]);
    }

    /// `--graph` is rejected rather than silently empty: an empty `graph_fields` means this store has no
    /// graph projection, and answering the flag with `[]` would read as "no networks".
    #[test]
    fn spec_declares_no_graph_projection() {
        assert!(SPEC.graph_fields.is_empty());
    }

    /// The help system is two-tier (#1762): a compact overview that names every command, and a detailed
    /// per-command drill-in. A command missing from the catalog is unreachable from help even when it
    /// dispatches, which is how a verb goes undiscovered.
    #[test]
    fn help_overview_lists_commands_and_per_command_help_drills_in() {
        for name in ["list", "get", "set", "remove"] {
            let doc = COMMANDS.iter().find(|c| c.name == name);
            let doc = doc.unwrap_or_else(|| panic!("`{name}` is missing from the help catalog"));
            assert!(!doc.summary.is_empty(), "`{name}` has a summary for the overview");
            assert!(
                doc.usage.contains(&format!("bsc network {name}")),
                "`{name}`'s detailed usage names the full command",
            );
        }
    }

    /// The id is load-bearing beyond this store — it derives the architect's pane id and workspace dir —
    /// so `set`'s help has to say the id is frozen and the name is what you rename. Documented behaviour
    /// with no test is how a contract quietly stops being true.
    #[test]
    fn set_help_states_the_id_is_frozen_and_the_name_is_not() {
        let set = COMMANDS.iter().find(|c| c.name == "set").expect("set is in the catalog");
        assert!(set.usage.contains("frozen at creation"));
        assert!(set.usage.contains("network-<id>:architect"));
    }
}
